package au.edu.uow.csci318.planning.application;import au.edu.uow.csci318.planning.dto.PlanningDtos.*;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.lang.reflect.*;import java.time.*;import java.util.*;
@Component public class StudyPlanningAgent{private final PlanningTools tools;private final ObjectMapper json;private final String apiKey;private final String model;public StudyPlanningAgent(PlanningTools tools,ObjectMapper json,@Value("${study.ai.api-key:}")String key,@Value("${study.ai.model:gpt-4.1-mini}")String model){this.tools=tools;this.json=json;apiKey=key;this.model=model;}
 public List<PlanItem>generate(PlanRequest request){List<AssessmentView>work=tools.getIncompleteAssessments();if(!apiKey.isBlank())try{return ai(request,work);}catch(Exception ignored){}return deterministic(request,work);}
 private List<PlanItem>deterministic(PlanRequest r,List<AssessmentView>work){List<AssessmentView>sorted=work.stream().filter(a->a.dueDate()==null||!a.dueDate().isBefore(r.startDate())).sorted(Comparator.comparing((AssessmentView a)->a.dueDate()==null?LocalDate.MAX:a.dueDate()).thenComparing(a->"HIGH".equals(a.priority())?0:1).thenComparing(a->a.weighting()==null?0:-a.weighting())).toList();List<PlanItem>items=new ArrayList<>();Map<UUID,Integer>remaining=new HashMap<>();sorted.forEach(a->remaining.put(a.id(),a.estimatedMinutes()==null?120:a.estimatedMinutes()));for(int d=0;d<7;d++){LocalDate date=r.startDate().plusDays(d);int available=r.dailyAvailabilityMinutes().getOrDefault(date,0);for(var a:sorted){if(available<=0)break;if(a.dueDate()!=null&&date.isAfter(a.dueDate()))continue;int left=remaining.get(a.id());if(left<=0)continue;int minutes=Math.min(Math.min(available,left),90);items.add(new PlanItem(date,a.subjectId(),a.id(),a.title(),minutes));remaining.put(a.id(),left-minutes);available-=minutes;}}return items;}
 private List<PlanItem>ai(PlanRequest r,List<AssessmentView>work)throws Exception{Class<?> c=Class.forName("dev.langchain4j.model.openai.OpenAiChatModel");Object b=c.getMethod("builder").invoke(null);b.getClass().getMethod("apiKey",String.class).invoke(b,apiKey);b.getClass().getMethod("modelName",String.class).invoke(b,model);Object chat=b.getClass().getMethod("build").invoke(b);String prompt="You are a goal-oriented study planner. These records came from approved getIncompleteAssessments(). Return ONLY a JSON array of {date,subjectId,assessmentId,title,allocatedMinutes}. Do not reference other IDs, completed work, dates outside the period, or exceed availability. period="+r.startDate()+".."+r.startDate().plusDays(6)+" availability="+json.writeValueAsString(r.dailyAvailabilityMinutes())+" assessments="+json.writeValueAsString(work);Method m=Arrays.stream(chat.getClass().getMethods()).filter(x->x.getName().equals("chat")&&x.getParameterCount()==1&&x.getParameterTypes()[0]==String.class).findFirst().orElseThrow();String raw=(String)m.invoke(chat,prompt);raw=raw.replaceFirst("(?s)^```(?:json)?\\s*","").replaceFirst("(?s)\\s*```$","");return json.readValue(raw,new TypeReference<List<PlanItem>>(){});}
}
